                                    continue
                                temp = best_seqs[r1][:]
                                temp.pop(pos1)
                                ins = pos2
                                if pos2 > pos1:
                                    ins -= 1
                                temp.insert(ins, p)
                                cand_seqs = [s[:] for s in best_seqs]
                                cand_seqs[r1] = temp
                            else:
                                cand_seqs = [s[:] for s in best_seqs]
                                cand_seqs[r1] = base_r1[:]
                                cand = best_seqs[r2][:]
                                cand.insert(pos2, p)
                                cand_seqs[r2] = cand

                            ok, c, _ = all_times(cand_seqs)
                            if ok and c + 1e-7 < current_cost:
                                best_seqs = cand_seqs
                                best_cost = c
                                improved = True
                                break
                        if improved:
