def solve(**kwargs):
    import time

    start_time = time.time()
    deadline = start_time + 8.5

    m = kwargs.get("m", 0)
    stocks = kwargs.get("stocks", [])
    pieces = kwargs.get("pieces", [])

    eps = 1e-9

    def fits_piece_in_stock(pl, pw, sl, sw):
        return (pl <= sl + eps and pw <= sw + eps) or (pw <= sl + eps and pl <= sw + eps)

    def orientations_that_fit(pl, pw, sl, sw):
        res = []
        if pl <= sl + eps and pw <= sw + eps:
            res.append((pl, pw, 0))
        if pw <= sl + eps and pl <= sw + eps and abs(pl - pw) > eps:
            res.append((pw, pl, 1))
        elif pw <= sl + eps and pl <= sw + eps and not res:
            res.append((pw, pl, 1))
        return res

    # Build required item list using minimum quantities.
    counts = []
    for p in pieces:
        mn = int(p.get("min", 0))
        mx = int(p.get("max", mn))
        if mn < 0:
            mn = 0
        if mx < mn:
            mx = mn
        counts.append(mn)

    if sum(counts) == 0:
        return {"objective": 0.0, "placements": {}}

    items = []
    total_used_area = 0.0
    for i, p in enumerate(pieces):
        l = float(p.get("length", 0.0))
        w = float(p.get("width", 0.0))
        area = l * w
        total_used_area += area * counts[i]
        for _ in range(counts[i]):
            items.append((i + 1, l, w, area))

    # Sort larger / harder pieces first.
    items.sort(key=lambda x: (max(x[1], x[2]), x[3], min(x[1], x[2])), reverse=True)

    def pack_items_for_stock(item_list, stock_index):
        if time.time() > deadline:
            return None

        st = stocks[stock_index]
        sl = float(st.get("length", 0.0))
        sw = float(st.get("width", 0.0))
        stock_area = sl * sw
        if sl <= 0 or sw <= 0:
            return None

        # Check feasibility of every item.
        for _, pl, pw, _ in item_list:
            if not fits_piece_in_stock(pl, pw, sl, sw):
                return None

        instances = []

        def make_instance():
            return {
                "stock_type": stock_index + 1,
                "placements": [],
                "_shelves": [],
                "_next_y": 0.0
            }

        for piece_id, pl, pw, _area in item_list:
            if time.time() > deadline:
                return None

            placed = False

            # Try existing shelves in existing stock instances.
            for inst in instances:
                shelves = inst["_shelves"]
                best_choice = None

                for si, shelf in enumerate(shelves):
                    sh = shelf["h"]
                    sx = shelf["x"]

                    # Prefer non-rotated if both work, but choose lower leftover width.
                    cand_orients = []
                    if pw <= sh + eps and pl <= sl - sx + eps:
                        cand_orients.append((pl, pw, 0))
                    if pl <= sh + eps and pw <= sl - sx + eps:
                        cand_orients.append((pw, pl, 1))

                    for ow, oh, ori in cand_orients:
                        leftover = (sl - sx - ow)
                        if best_choice is None or leftover < best_choice[0]:
                            best_choice = (leftover, si, ow, oh, ori)

                if best_choice is not None:
                    _, si, ow, oh, ori = best_choice
                    shelf = shelves[si]
                    inst["placements"].append({
                        "piece": piece_id,
                        "x": shelf["x"],
                        "y": shelf["y"],
                        "orientation": ori
                    })
                    shelf["x"] += ow
                    placed = True
                    break

            if placed:
                continue

            # Try creating a new shelf in an existing stock instance.
            for inst in instances:
                cand_orients = orientations_that_fit(pl, pw, sl, sw)
                # Choose orientation with larger shelf height first for stability.
                cand_orients.sort(key=lambda t: (t[1], t[0]), reverse=True)

                for ow, oh, ori in cand_orients:
                    if inst["_next_y"] + oh <= sw + eps and ow <= sl + eps:
                        y = inst["_next_y"]
                        inst["placements"].append({
                            "piece": piece_id,
                            "x": 0.0,
                            "y": y,
                            "orientation": ori
                        })
                        inst["_shelves"].append({"y": y, "h": oh, "x": ow})
                        inst["_next_y"] += oh
                        placed = True
                        break
                if placed:
                    break

            if placed:
                continue

            # Open a new stock instance.
            inst = make_instance()
            cand_orients = orientations_that_fit(pl, pw, sl, sw)
            if not cand_orients:
                return None
            cand_orients.sort(key=lambda t: (t[1], t[0]), reverse=True)
            ow, oh, ori = cand_orients[0]
            inst["placements"].append({
                "piece": piece_id,
                "x": 0.0,
                "y": 0.0,
                "orientation": ori
            })
            inst["_shelves"].append({"y": 0.0, "h": oh, "x": ow})
            inst["_next_y"] = oh
            instances.append(inst)

        clean = []
        for inst in instances:
            clean.append({
                "stock_type": inst["stock_type"],
                "placements": inst["placements"]
            })

        return clean, len(instances) * stock_area

    def build_solution_from_groups(groups):
        all_instances = []
        total_stock_area = 0.0

        for stock_index, group_items in groups:
            if not group_items:
                continue
            res = pack_items_for_stock(group_items, stock_index)
            if res is None:
                return None
            insts, area = res
            all_instances.extend(insts)
            total_stock_area += area

        if total_stock_area <= eps:
            return None

        obj = max(0.0, (total_stock_area - total_used_area) / total_stock_area)
        placements = {}
        for idx, inst in enumerate(all_instances, 1):
            placements[idx] = inst

        return {"objective": obj, "placements": placements}

    best = None
    best_obj = None

    nstocks = len(stocks)

    # Try each single stock type.
    for si in range(nstocks):
        if time.time() > deadline:
            break
        feasible = True
        sl = float(stocks[si].get("length", 0.0))
        sw = float(stocks[si].get("width", 0.0))
        for p in pieces:
            if int(p.get("min", 0)) > 0 and not fits_piece_in_stock(
                float(p.get("length", 0.0)), float(p.get("width", 0.0)), sl, sw
            ):
                feasible = False
                break
        if not feasible:
            continue

        sol = build_solution_from_groups([(si, items)])
        if sol is not None:
            if best is None or sol["objective"] < best_obj:
                best = sol
                best_obj = sol["objective"]

    # Try pairs of stock types. Assign each piece type to the smaller-area feasible stock.
    for a in range(nstocks):
        if time.time() > deadline:
            break
        for b in range(a + 1, nstocks):
            if time.time() > deadline:
                break

            area_a = float(stocks[a].get("length", 0.0)) * float(stocks[a].get("width", 0.0))
            area_b = float(stocks[b].get("length", 0.0)) * float(stocks[b].get("width", 0.0))
            group_a = []
            group_b = []
            feasible = True

            for item in items:
                _, pl, pw, _ = item
                fa = fits_piece_in_stock(pl, pw, float(stocks[a].get("length", 0.0)), float(stocks[a].get("width", 0.0)))
                fb = fits_piece_in_stock(pl, pw, float(stocks[b].get("length", 0.0)), float(stocks[b].get("width", 0.0)))

                if not fa and not fb:
                    feasible = False
                    break
                if fa and fb:
                    if area_a <= area_b:
                        group_a.append(item)
                    else:
                        group_b.append(item)
                elif fa:
                    group_a.append(item)
                else:
                    group_b.append(item)

            if not feasible:
                continue

            sol = build_solution_from_groups([(a, group_a), (b, group_b)])
            if sol is not None:
                if best is None or sol["objective"] < best_obj:
                    best = sol
                    best_obj = sol["objective"]

    # Fallback: place each piece in its own smallest feasible stock.
    if best is None:
        placements = {}
        total_stock_area = 0.0
        sid = 1

        for piece_id, pl, pw, area in items:
            chosen = None
            chosen_area = None
            chosen_ori = 0

            for si, st in enumerate(stocks):
                sl = float(st.get("length", 0.0))
                sw = float(st.get("width", 0.0))
                if sl <= 0 or sw <= 0:
                    continue

                if pl <= sl + eps and pw <= sw + eps:
                    sa = sl * sw
                    if chosen is None or sa < chosen_area:
                        chosen = si
                        chosen_area = sa
                        chosen_ori = 0

                if pw <= sl + eps and pl <= sw + eps:
                    sa = sl * sw
                    if chosen is None or sa < chosen_area:
                        chosen = si
                        chosen_area = sa
                        chosen_ori = 1

            if chosen is None:
                # Truly infeasible; return empty rather than malformed geometry.
                return {"objective": 0.0, "placements": {}}

            placements[sid] = {
                "stock_type": chosen + 1,
                "placements": [{
                    "piece": piece_id,
                    "x": 0.0,
                    "y": 0.0,
                    "orientation": chosen_ori
                }]
            }
            total_stock_area += chosen_area
            sid += 1

        obj = max(0.0, (total_stock_area - total_used_area) / total_stock_area) if total_stock_area > eps else 0.0
        best = {"objective": obj, "placements": placements}

    return best
