def solve(**kwargs):
    import time
    import math
    import random

    start_time = time.time()
    deadline = start_time + 8.5

    planes = kwargs["planes"]
    n = int(kwargs["num_planes"])
    m = max(1, int(kwargs["num_runways"]))
    sep = kwargs["separation"]

    earliest = [float(p["earliest"]) for p in planes]
    target = [float(p["target"]) for p in planes]
    latest = [float(p["latest"]) for p in planes]
    pe = [float(p["penalty_early"]) for p in planes]
    pl = [float(p["penalty_late"]) for p in planes]

    def penalty(i, t):
        if t <= target[i]:
            return (target[i] - t) * pe[i]
        return (t - target[i]) * pl[i]

    def optimize_sequence(seq):
        """Return (feasible, times_dict, cost) for a fixed runway order."""
        k = len(seq)
        if k == 0:
            return True, {}, 0.0

        lo = [0.0] * k
        hi = [0.0] * k

        for a, i in enumerate(seq):
            if a == 0:
                lo[a] = earliest[i]
            else:
                prev = seq[a - 1]
                lo[a] = max(earliest[i], lo[a - 1] + float(sep[prev][i]))

        for a in range(k - 1, -1, -1):
            i = seq[a]
            if a == k - 1:
                hi[a] = latest[i]
            else:
                nxt = seq[a + 1]
                hi[a] = min(latest[i], hi[a + 1] - float(sep[i][nxt]))

        for a in range(k):
            if lo[a] > hi[a] + 1e-9:
                return False, {}, float("inf")

        # Start as early as possible, then push aircraft rightwards toward target
        # without breaking successors. This is fast and usually much better than
        # pure earliest scheduling.
        t = lo[:]
        for a in range(k - 1, -1, -1):
            i = seq[a]
            upper = hi[a]
            if a < k - 1:
                nxt = seq[a + 1]
                upper = min(upper, t[a + 1] - float(sep[i][nxt]))
            if t[a] < target[i]:
                t[a] = min(target[i], upper)
            elif t[a] > upper:
                t[a] = upper
            if t[a] < lo[a]:
                t[a] = lo[a]

        # Small forward repair for numerical safety.
        for a in range(1, k):
            prev = seq[a - 1]
            i = seq[a]
            need = t[a - 1] + float(sep[prev][i])
            if t[a] < need:
                t[a] = need
                if t[a] > hi[a] + 1e-7:
                    return False, {}, float("inf")

        c = 0.0
        d = {}
        for a, i in enumerate(seq):
            ti = min(max(t[a], earliest[i]), latest[i])
            d[i] = ti
            c += penalty(i, ti)
        return True, d, c

    def evaluate_sequences(sequences):
        all_times = {}
        total = 0.0
        for seq in sequences:
            ok, td, c = optimize_sequence(seq)
            if not ok:
                return False, {}, float("inf")
            all_times.update(td)
            total += c
        return len(all_times) == n, all_times, total

    def build_append(order):
        sequences = [[] for _ in range(m)]
        approx_last = [-10**30] * m

        for i in order:
            if time.time() > deadline:
                break
            best_r = None
            best_score = float("inf")
            for r in range(m):
                if not sequences[r]:
                    t0 = min(max(target[i], earliest[i]), latest[i])
                    if earliest[i] <= t0 <= latest[i]:
                        score = penalty(i, t0)
                    else:
                        continue
                else:
                    prev = sequences[r][-1]
                    lb = approx_last[r] + float(sep[prev][i])
                    t0 = max(earliest[i], lb)
                    if t0 <= target[i] <= latest[i] and target[i] >= lb:
                        t0 = target[i]
                    if t0 > latest[i] + 1e-9:
                        continue
                    score = penalty(i, t0) + 0.001 * t0
                if score < best_score:
                    best_score = score
                    best_r = r

            if best_r is None:
                # Choose the runway that gives the least lateness violation;
                # later global evaluation may still fail, but this keeps going.
                best_r = 0
                best_val = float("inf")
                for r in range(m):
                    if not sequences[r]:
                        lb = earliest[i]
                    else:
                        prev = sequences[r][-1]
                        lb = max(earliest[i], approx_last[r] + float(sep[prev][i]))
                    val = max(0.0, lb - latest[i])
                    if val < best_val:
                        best_val = val
                        best_r = r

            sequences[best_r].append(i)
            # maintain a cheap feasible-ish last estimate
            if len(sequences[best_r]) == 1:
                approx_last[best_r] = min(max(target[i], earliest[i]), latest[i])
            else:
                prev = sequences[best_r][-2]
                lb = approx_last[best_r] + float(sep[prev][i])
                approx_last[best_r] = min(max(target[i], earliest[i], lb), latest[i])

        return sequences

    def build_insertion(order):
        sequences = [[] for _ in range(m)]
        current_cost = 0.0

        for idx, i in enumerate(order):
            if time.time() > deadline:
                return sequences

            best = None
            best_cost = float("inf")

            for r in range(m):
                seq = sequences[r]
                # Limit insertion positions for larger instances.
                if n <= 60:
                    positions = range(len(seq) + 1)
                else:
                    positions = (len(seq),)

                for pos in positions:
                    trial_seq = seq[:pos] + [i] + seq[pos:]
                    ok, _, c = optimize_sequence(trial_seq)
                    if not ok:
                        continue

                    old_ok, _, old_c = optimize_sequence(seq)
                    if not old_ok:
                        old_c = 0.0

                    delta = c - old_c
                    if delta < best_cost:
                        best_cost = delta
                        best = (r, pos)

            if best is None:
                # Fallback to append on the shortest runway.
                r = min(range(m), key=lambda x: len(sequences[x]))
                sequences[r].append(i)
            else:
                r, pos = best
                sequences[r].insert(pos, i)
                current_cost += best_cost

        return sequences

    orders = []
    ids = list(range(n))
    orders.append(sorted(ids, key=lambda i: (target[i], latest[i])))
    orders.append(sorted(ids, key=lambda i: (latest[i], target[i])))
    orders.append(sorted(ids, key=lambda i: (earliest[i], target[i])))
    orders.append(sorted(ids, key=lambda i: (target[i] - earliest[i], latest[i])))
    orders.append(sorted(ids, key=lambda i: (latest[i] - target[i], target[i])))

    # A few deterministic randomized perturbations for small/medium instances.
    if n <= 120:
        rng = random.Random(12345)
        base = sorted(ids, key=lambda i: target[i])
        for _ in range(4):
            arr = base[:]
            width = max(2, min(10, n // 5 + 1))
            for a in range(n):
                b = min(n - 1, max(0, a + rng.randint(-width, width)))
                arr[a], arr[b] = arr[b], arr[a]
            orders.append(arr)

    best_sequences = None
    best_times = None
    best_cost = float("inf")

    for order in orders:
        if time.time() > deadline:
            break

        if n <= 80:
            seqs = build_insertion(order)
        else:
            seqs = build_append(order)

        ok, times, cost = evaluate_sequences(seqs)
        if ok and cost < best_cost:
            best_cost = cost
            best_sequences = seqs
            best_times = times

    # If no feasible candidate was found, try a very conservative append by latest.
    if best_times is None:
        seqs = build_append(sorted(ids, key=lambda i: latest[i]))
        ok, times, cost = evaluate_sequences(seqs)
        if ok:
            best_sequences = seqs
            best_times = times
            best_cost = cost

    # Final absolute fallback: assign greedily at earliest feasible times.
    # This may be infeasible on difficult instances, but returns a complete schedule.
    if best_times is None:
        sequences = [[] for _ in range(m)]
        times = {}
        last_time = [-10**30] * m
        last_plane = [None] * m

        for i in sorted(ids, key=lambda x: latest[x]):
            best_r = 0
            best_t = float("inf")
            for r in range(m):
                if last_plane[r] is None:
                    t = earliest[i]
                else:
                    t = max(earliest[i], last_time[r] + float(sep[last_plane[r]][i]))
                if t < best_t:
                    best_t = t
                    best_r = r
            if best_t > latest[i]:
                best_t = latest[i]
            sequences[best_r].append(i)
            times[i] = best_t
            last_time[best_r] = best_t
            last_plane[best_r] = i

        best_sequences = sequences
        best_times = times

    # Optional final local improvement by moving single planes between append positions.
    if best_sequences is not None and n <= 70 and time.time() < deadline:
        improved = True
        while improved and time.time() < deadline:
            improved = False
            base_ok, base_times, base_cost = evaluate_sequences(best_sequences)
            if not base_ok:
                break

            for i in ids:
                if time.time() > deadline:
                    break

                cur_r = None
                cur_pos = None
                for r in range(m):
                    if i in best_sequences[r]:
                        cur_r = r
                        cur_pos = best_sequences[r]..index(i)
                        break
                if cur_r is None:
                    continue

                trial_base = [s[:] for s in best_sequences]
                trial_base[cur_r].pop(cur_pos)

                local_best = None
                local_cost = base_cost

                for r in range(m):
                    for pos in range(len(trial_base[r]) + 1):
                        trial = [s[:] for s in trial_base]
                        trial[r].insert(pos, i)
                        ok, _, c = evaluate_sequences(trial)
                        if ok and c + 1e-7 < local_cost:
                            local_cost = c
                            local_best = trial

                if local_best is not None:
                    best_sequences = local_best
                    best_cost = local_cost
                    improved = True
                    break

        ok, times, cost = evaluate_sequences(best_sequences)
        if ok:
            best_times = times

    runway_of = {}
    for r, seq in enumerate(best_sequences):
        for i in seq:
            runway_of[i] = r + 1

    schedule = {}
    for i in range(n):
        t = best_times.get(i, min(max(target[i], earliest[i]), latest[i]))
        if t < earliest[i]:
            t = earliest[i]
        if t > latest[i]:
            t = latest[i]
        schedule[i + 1] = {
            "landing_time": float(t),
            "runway": int(runway_of.get(i, (i % m) + 1)),
        }

    return {"schedule": schedule}
